#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Configura a Azure (Azure for Students) como provedor de cloud do Garage Flow API.
# Uso: infra/scripts/setup-azure.sh   (pode ser executado novamente: lembra as escolhas)

run_wizard() {

TOTAL_STAGES=8

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

# No Windows, o az CLI usa por padrão o WAM (janela de contas do sistema), que nem sempre
# conclui o login. Desligado, o `az login` abre a página da Microsoft no navegador.
export AZURE_CORE_ENABLE_BROKER_ON_WINDOWS=false

# No Git Bash, o az (programa Windows) termina as linhas com CRLF: o \r quebra comparações
# e IDs capturados com $(az ...). Remove o \r de toda a saída do az.
if [[ "${OSTYPE:-}" == msys* || "${OSTYPE:-}" == cygwin* ]]; then
  az() { command az "$@" | tr -d '\r'; }
fi

# Valores lembrados entre execuções (ignorado pelo Git); carregado por infra/scripts/lib.sh.
ENV_FILE="infra/azure/.env.azure"
TFVARS="infra/azure/environments/${ENVIRONMENT:-staging}.tfvars"

REQUIRED_PROVIDERS=(
  Microsoft.ContainerService
  Microsoft.ContainerRegistry
  Microsoft.DBforPostgreSQL
  Microsoft.KeyVault
  Microsoft.Network
  Microsoft.Compute
  Microsoft.Storage
  Microsoft.ManagedIdentity
)

tfvars_get() { sed -n "s/^${1}[[:space:]]*=[[:space:]]*\"\{0,1\}\([^\"]*\)\"\{0,1\}.*/\1/p" "$TFVARS" | head -n 1; }

# Substitui (ou acrescenta) `key = "value"` no tfvars.
tfvars_set() {
  local key="$1" value="$2" tmp
  tmp=$(mktemp)
  if grep -qE "^${key}[[:space:]]*=" "$TFVARS"; then
    # Preserva o alinhamento original (terraform fmt).
    sed -E "s|^(${key}[[:space:]]*=[[:space:]]*).*|\1\"${value}\"|" "$TFVARS" > "$tmp"
  else
    cat "$TFVARS" > "$tmp"
    printf '%s = "%s"\n' "$key" "$value" >> "$tmp"
  fi
  cat "$tmp" > "$TFVARS"
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s = "%s" → %s\n' "$GREEN" "$RESET" "$key" "$value" "$TFVARS"
}

# Verifica se a região comporta a stack. Retorna 1 se algum requisito falhar.
check_region() {
  local loc="$1" vm_size node_count sku vcpus family restrictions needed usage ok=0 name current limit
  vm_size=$(tfvars_get node_vm_size); vm_size="${vm_size:-Standard_B2als_v2}"
  node_count=$(tfvars_get node_count); node_count="${node_count:-2}"

  say "Verificando ${BOLD}${loc}${RESET} (leva alguns segundos)..."

  # 1. VM dos nodes disponível para a assinatura nesta região.
  # Lista de linhas ([?...].[...]): o TSV sai como uma linha "vCPUs<TAB>família<TAB>restrições".
  sku=$(az vm list-skus --location "$loc" --size "$vm_size" --resource-type virtualMachines \
    --query "[?name=='${vm_size}'].[capabilities[?name=='vCPUs'].value | [0], family, join(',', restrictions[].reasonCode)]" \
    --output tsv 2>/dev/null | head -n 1 || true)
  if [[ -z "$sku" ]]; then
    warn "VM ${vm_size} não é oferecida em ${loc} para esta assinatura."
    note "Tamanhos x86 de 2 vCPUs disponíveis aparecem com:"
    note "  az vm list-skus -l ${loc} --size Standard_B2 --resource-type virtualMachines --query \"[?restrictions==\\\`[]\\\`].name\" -o tsv"
    note "Ajuste node_vm_size em ${TFVARS} (evite tamanhos com 'p', que são ARM)."
    return 1
  fi
  vcpus=$(printf '%s' "$sku" | cut -f1)
  family=$(printf '%s' "$sku" | cut -f2)
  restrictions=$(printf '%s' "$sku" | cut -f3)
  [[ "$vcpus" =~ ^[0-9]+$ ]] || vcpus=2
  if [[ -n "$restrictions" ]]; then
    warn "VM ${vm_size} restrita em ${loc} para esta assinatura (${restrictions})."
    ok=1
  else
    say "${GREEN}✓${RESET} VM ${vm_size} disponível (${vcpus} vCPUs)"
  fi

  # 2. Quota de vCPUs (total da região e da família da VM): nodes + 1 node extra usado
  #    durante upgrades do AKS.
  needed=$(( (node_count + 1) * ${vcpus:-2} ))
  # Captura antes do loop, sem process substitution: funciona também via `sh` (bash em modo POSIX).
  usage=$(az vm list-usage --location "$loc" \
    --query "[?name.value=='cores' || name.value=='${family}'].[name.value, currentValue, limit]" \
    --output tsv 2>/dev/null || true)
  while IFS=$'\t' read -r name current limit; do
    [[ -z "$name" ]] && continue
    if (( limit - current < needed )); then
      warn "Quota ${name}: ${current}/${limit} em uso, a stack precisa de ${needed} vCPUs livres."
      ok=1
    else
      say "${GREEN}✓${RESET} Quota ${name}: $((limit - current)) vCPUs livres (precisa de ${needed})"
    fi
  done <<USAGE
${usage}
USAGE

  # 3. PostgreSQL Flexible Server com o SKU configurado.
  # Captura antes do grep: com `| grep -q` direto, o grep fecha o pipe no primeiro match,
  # o az recebe SIGPIPE e o pipefail transforma o sucesso em falha.
  local pg_skus
  pg_skus=$(az postgres flexible-server list-skus --location "$loc" --output json 2>/dev/null || true)
  if grep -q '"Standard_B1ms"' <<<"$pg_skus"; then
    say "${GREEN}✓${RESET} PostgreSQL Flexible Server (B1ms) disponível"
  else
    warn "PostgreSQL Flexible Server B1ms indisponível ou restrito em ${loc}."
    ok=1
  fi

  return "$ok"
}

banner "Garage Flow API · configuração da Azure"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Ferramentas locais"
say "Conferindo as ferramentas usadas pelos scripts de infraestrutura."
missing=()
for cmd in terraform az kubectl docker; do
  if command -v "$cmd" >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} ${cmd}"
  else
    warn "${cmd} não encontrado"
    missing+=("$cmd")
  fi
done
if (( ${#missing[@]} )); then
  note "Instale com: brew tap hashicorp/tap && brew install hashicorp/tap/terraform azure-cli kubectl"
  note "Docker: instale e abra o Docker Desktop."
  exit 1
fi
if docker info >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} Docker em execução"
else
  warn "Docker instalado, mas parado. Abra o Docker Desktop (necessário só no deploy da aplicação)."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Login na Azure"
if account=$(az account show --query "user.name" --output tsv 2>/dev/null); then
  say "Sessão ativa no az CLI como ${BOLD}${account}${RESET}."
  if confirm "Entrar com outra conta?"; then
    az logout >/dev/null 2>&1 || true
    account=""
  fi
fi
if [[ -z "${account:-}" ]]; then
  say "O navegador vai abrir a página de login da Microsoft."
  step "Entre com a conta da universidade vinculada ao Azure for Students."
  step "Se o terminal pedir para escolher uma assinatura, aceite a padrão (será ajustada no próximo passo)."
  az login --output none
fi
say "${GREEN}✓${RESET} Logado como $(az account show --query user.name --output tsv)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Assinatura"
pinned_subscription=$(tfvars_get subscription_id)
if [[ -n "$pinned_subscription" ]]; then
  # Assinatura do grupo fixada no tfvars: não pergunta, só confere o acesso.
  say "Assinatura fixada em ${TFVARS}: ${BOLD}${pinned_subscription}${RESET}"
  if ! az account set --subscription "$pinned_subscription" >/dev/null 2>&1; then
    warn "Sua conta não tem acesso a essa assinatura."
    note "Peça ao dono da assinatura uma role no IAM (ver infra/README.md, 'Acesso do grupo')."
    note "Para usar outra assinatura, veja infra/README.md, 'Trocar a assinatura Azure'."
    exit 1
  fi
  ARM_SUBSCRIPTION_ID="$pinned_subscription"
else
  say "Assinaturas disponíveis para esta conta:"
  az account list --query "[].{Nome:name, ID:id, Estado:state, Atual:isDefault}" --output table | sed 's/^/    /'
  note "Use a assinatura 'Azure for Students' (Estado = Enabled)."
  note "Sem nenhuma? Ative em https://azure.microsoft.com/free/students com o e-mail da universidade."
  until ask ARM_SUBSCRIPTION_ID "ID da assinatura (Enter usa a Atual):" &&
    { [[ -n "$ARM_SUBSCRIPTION_ID" ]] || ARM_SUBSCRIPTION_ID=$(az account show --query id --output tsv); } &&
    az account set --subscription "$ARM_SUBSCRIPTION_ID" >/dev/null 2>&1; do
    warn "Assinatura inválida ou inacessível. Copie o ID da tabela acima."
  done
fi
write_env ARM_SUBSCRIPTION_ID "$ARM_SUBSCRIPTION_ID"
say "${GREEN}✓${RESET} Assinatura ativa: $(az account show --query name --output tsv)"

# Key Vault em modo RBAC: só quem está em secrets_officer_object_ids mantém acesso aos secrets.
user_object_id=$(az ad signed-in-user show --query id --output tsv 2>/dev/null || true)
if [[ -n "$user_object_id" ]] && ! grep -q "\"${user_object_id}\"" "$TFVARS"; then
  warn "Seu object ID (${user_object_id}) não está em secrets_officer_object_ids (${TFVARS})."
  note "Sem ele na lista, você perde o acesso aos secrets do Key Vault quando outra pessoa aplicar."
  note "Peça para incluí-lo ou adicione-o ao tfvars. Detalhes: infra/README.md, 'Acesso do grupo'."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Registro dos serviços (resource providers)"
say "Assinaturas novas precisam habilitar cada serviço Azure antes do primeiro uso."
note "Execução única por assinatura; pode levar alguns minutos."
for ns in "${REQUIRED_PROVIDERS[@]}"; do
  state=$(az provider show --namespace "$ns" --query registrationState --output tsv 2>/dev/null || echo "NotRegistered")
  if [[ "$state" == "Registered" ]]; then
    say "${GREEN}✓${RESET} ${ns}"
  else
    say "… registrando ${ns}"
    az provider register --namespace "$ns" --wait --output none
    say "${GREEN}✓${RESET} ${ns}"
  fi
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Região"
say "Assinaturas Azure for Students só podem criar recursos em algumas regiões."
allowed=$(az policy assignment list --disable-scope-strict-match \
  --query "[].parameters.listOfAllowedLocations.value[]" --output tsv 2>/dev/null | sort -u | tr '\n' ' ' || true)
if [[ -n "${allowed// /}" ]]; then
  say "Regiões permitidas pela policy da assinatura: ${BOLD}${allowed}${RESET}"
else
  note "Nenhuma policy de regiões encontrada (ou sem permissão para lê-la)."
fi
note "Sugestões próximas ao Brasil com bom custo: eastus2, eastus, centralus, brazilsouth (mais cara)."
current_location=$(tfvars_get location)
while true; do
  [[ -z "$(_existing AZURE_LOCATION || true)" && -n "$current_location" ]] && note "Atual no tfvars: ${current_location}"
  ask AZURE_LOCATION "Região (ex.: eastus2):"
  AZURE_LOCATION="${AZURE_LOCATION:-$current_location}"
  if [[ -n "${allowed// /}" && " ${allowed} " != *" ${AZURE_LOCATION} "* ]]; then
    warn "${AZURE_LOCATION} não está na lista de regiões permitidas."
    continue
  fi
  if check_region "$AZURE_LOCATION"; then
    break
  fi
  confirm "Usar ${AZURE_LOCATION} mesmo assim?" && break
done
write_env AZURE_LOCATION "$AZURE_LOCATION"
tfvars_set location "$AZURE_LOCATION"
note "O state remoto (bootstrap) também será criado nesta região."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Validação do Terraform"
say "Baixando os providers e validando o código (sem criar nada na Azure)."
for dir in infra/azure/bootstrap infra/azure; do
  say "… ${dir}"
  terraform -chdir="$dir" init -backend=false -input=false >/dev/null
  terraform -chdir="$dir" validate
done
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Provisionar a infraestrutura"
say "Cria state remoto, rede, AKS, PostgreSQL, ACR, Key Vault e Ingress Controller."
note "Leva ~15-20 minutos e consome créditos (~US\$ 3/dia enquanto existir)."
note "O próprio script mostra o plano e pede confirmação ('sim') antes de aplicar."
if confirm "Provisionar agora?"; then
  infra/scripts/provision.sh azure
else
  SKIPPED+=("Provisionar: infra/scripts/provision.sh azure")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy da aplicação"
if ! terraform -chdir=infra/azure output -raw cluster_name >/dev/null 2>&1; then
  note "Infraestrutura ainda não provisionada; pulando."
  SKIPPED+=("Deploy: infra/scripts/deploy-app.sh azure (após provisionar)")
elif ! docker info >/dev/null 2>&1; then
  warn "Docker parado: abra o Docker Desktop e rode o deploy depois."
  SKIPPED+=("Deploy: infra/scripts/deploy-app.sh azure")
else
  say "Build e push das imagens no ACR, migrations, primeiro admin e API."
  if confirm "Fazer o deploy agora?"; then
    infra/scripts/deploy-app.sh azure
  else
    SKIPPED+=("Deploy: infra/scripts/deploy-app.sh azure")
  fi
fi
SKIPPED+=("Ao terminar a sessão: infra/scripts/destroy.sh azure (encerra a cobrança)")
pause

finish
}

run_wizard "$@"; exit
